      es: ["Reservas de carbón: 1.200 millones de toneladas", "Producción anual: 4 millones de toneladas", "Poder calorífico: 4.000 kcal/kg", "Operador: Baganuur JSC", "Distancia a Ulán Bator: 120 km", "Número de empleados: 800"],
