      en: ["Formerly the heart of Mongolia's coal mining sector.", "Located in the southeastern district of Ulaanbaatar.", "Focuses on the production of building materials.", "Aims to decentralize industry from the city center.", "Equipped with dedicated customs and logistics zones.", "Promotes green industrial and recycling technologies."],
      es: ["Año de fundación: 2020", "Superficie: 200 hectáreas", "Sectores clave: TI, biotecnología, energías renovables", "Primeras empresas: 5 instaladas", "Volumen de inversión: 20 millones de USD hasta ahora", "Puestos de trabajo previstos: 2.000"],
