    descriptionAdvanced: {
      de: "Die Ukhaa Khudag Kohlemine (UHG) befindet sich in der Region Süd-Gobi in der Mongolei und ist Teil des riesigen Tavan Tolgoi Kohlebeckens. Sie wird von der Mongolian Mining Corporation (MMC) betrieben und gilt als eine der modernsten Industrieanlagen des Landes. Besonders hervorzuheben ist die integrierte Kohlewaschanlage, die erste ihrer Art in der Mongolei, die es ermöglicht, die geförderte Rohkohle zu hochwertiger Kokskohle für den Export zu veredeln. Die Mine verfügt über eine eigene Infrastruktur, einschließlich eines 18-Megawatt-Kraftwerks und einer Wasserversorgungsanlage, um den Betrieb in der abgelegenen Wüste zu sichern. Das Projekt hat die wirtschaftliche Landschaft der Mongolei massiv verändert und den Bergbausektor auf ein neues technologisches Niveau gehoben. Die hier gewonnene Kohle wird hauptsächlich per LKW über dedizierte Transportwege zur chinesischen Grenze geliefert und spielt eine zentrale Rolle im mongolischen Außenhandel.",
      hu: "Az Ukhaa Khudag szénbánya (UHG) Mongólia déli Gobi régiójában található, a hatalmas Tavan Tolgoi szénmedence részeként. A Mongolian Mining Corporation (MMC) által üzemeltetett bánya az ország egyik legkorszerűbb ipari létesítménye. Kiemelkedő technológiai jellemzője az integrált szénmosó üzem, amely az első ilyen jellegű beruházás volt Mongóliában, lehetővé téve a kiváló minőségű kokszolható szén előállítását export célokra. A bánya teljes önellátásra törekszik a sivatagi környezetben: saját 18 megawattos erőművel és modern vízellátó rendszerrel rendelkezik. A projekt jelentősen hozzájárult Mongólia gazdasági növekedéséhez és a bányászati szektor modernizációjához. Az itt kitermelt szenet speciális útvonalakon, nehézgépjárművekkel szállítják a kínai határ felé, ami a mongol külkereskedelem egyik legfontosabb pillére. A bánya nemcsak nyersanyagforrás, hanem a technológiai fejlődés szimbóluma is a térségben.",
      ro: "Mina de cărbune Ukhaa Khudag (UHG) este situată în regiunea Gobi de Sud din Mongolia și face parte din vastul bazin carbonifer Tavan Tolgoi. Operată de Mongolian Mining Corporation (MMC), această mină este considerată una dintre cele mai avansate instalații industriale din țară. Un element definitoriu este unitatea integrată de spălare a cărbunelui, prima de acest fel din Mongolia, care permite rafinarea cărbunelui brut în cărbune cocsificabil de înaltă calitate destinat exportului. Mina beneficiază de o infrastructură proprie robustă, incluzând o centrală electrică de 18 megawați și sisteme de alimentare cu apă, esențiale pentru operarea într-un mediu deșertic izolat. Proiectul a avut un impact major asupra economiei Mongoliei, ridicând standardele tehnologice în sectorul extractiv. Cărbunele produs aici este transportat în principal cu camioane grele către frontiera chineză, reprezentând o componentă vitală a comerțului exterior mongol și a dezvoltării industriale regionale.",
      en: "The Ukhaa Khudag Coal Mine (UHG) is located in the South Gobi region of Mongolia, forming a crucial part of the massive Tavan Tolgoi coal deposit. Operated by the Mongolian Mining Corporation (MMC), it is recognized as one of the country's most sophisticated industrial operations. A standout feature of the site is its integrated coal handling and preparation plant—the first of its kind in Mongolia—which processes raw coal into high-value coking coal for export. The mine is a self-contained complex in the remote desert, supported by its own 18-megawatt power plant and a dedicated water supply system. This project has significantly transformed the Mongolian economic landscape by introducing modern mining technologies and international standards. The coal extracted here is primarily transported via heavy-duty trucks to the Chinese border, serving as a pillar of Mongolia's export economy and a key driver of regional industrial growth.",
      es: "La mina de carbón Ukhaa Khudag, en el sur de Mongolia, es un importante proveedor de carbón para el mercado nacional y para la exportación. La mina es operada por Energy Resources LLC y cuenta con unas reservas de más de 1.000 millones de toneladas de carbón. La producción anual es de unos 8 millones de toneladas. La mina es conocida por la alta calidad de su carbón y abastece, entre otros, a la central eléctrica de Tavan Tolgoi. La infraestructura incluye una conexión ferroviaria con China.",
      pt: "A mina de carvão Ukhaa Khudag, no sul da Mongólia, é um importante fornecedor de carvão para o mercado interno e para exportação. A mina é operada pela Energy Resources LLC e possui reservas de mais de 1 mil milhão de toneladas de carvão. A produção anual é de cerca de 8 milhões de toneladas. A mina é conhecida pela elevada qualidade do seu carvão e abastece, entre outras, a central elétrica de Tavan Tolgoi. A infraestrutura inclui uma ligação ferroviária para a China.",
      fr: "La mine de charbon d'Ukhaa Khudag, dans le sud de la Mongolie, est un fournisseur important de charbon pour le marché intérieur et l'exportation. La mine est exploitée par Energy Resources LLC et possède des réserves de plus d'un milliard de tonnes de charbon. La production annuelle est d'environ 8 millions de tonnes. La mine est réputée pour la haute qualité de son charbon et alimente, entre autres, la centrale électrique de Tavan Tolgoi. Les infrastructures comprennent une liaison ferroviaire vers la Chine.",
    },
